// Actual cartridge fixture. All four actors share one world; only the camera reads my_slot.
// The MP header is in physical bank 1, the context in unbanked WRAM, while gameplay selects bank 2.
import { fixHeader } from '../../../src/rom.ts';
export function gbMultiplayer(cgb) {
 const rom=new Uint8Array(32768), labels=new Map(), fixups=[];let pc=0x150;
 const emit=(...b)=>{rom.set(b,pc);pc+=b.length;};
 const label=n=>labels.set(n,pc);
 const jump=(op,n)=>{emit(op,0,0);fixups.push([pc-2,n]);};
 const store=(a,v)=>emit(0x3e,v,0xea,a&255,a>>8);
 emit(0xf3,0x31,0xff,0xdf);store(0xff40,0);
 emit(0x21,0,0xc0,0x01,0,0x20);label('clear');emit(0xaf,0x22,0x0b,0x78,0xb1);jump(0xc2,'clear');
 if(cgb)store(0xff70,1);
 for(const [i,v]of [0x4d,0x50,1,8,0,0xc4,32,1].entries())store(0xd0f0+i,v);
 label('bootstrap');emit(0xfa,7,0xc4,0xb7);jump(0xca,'bootstrap');
 // This marker remains zero for every neutral bootstrap frame.
 store(0xc010,0xa5);
 for(let i=0;i<4;i++){emit(0xfa,12,0xc4,0xc6,20+32*i,0xea,i,0xc0);}
 // Tile 0: diagonal pattern; tile 1: visible 8x8 actor.
 for(let y=0;y<8;y++){store(0x8000+y*2,0x80>>y);store(0x8001+y*2,0);store(0x8010+y*2,0xff);store(0x8011+y*2,0xff);}
 emit(0x21,0,0x98,0x01,0,4);label('map');emit(0xaf,0x22,0x0b,0x78,0xb1);jump(0xc2,'map');
 for(let i=0;i<160;i++)store(0xfe00+i,0);
 for(let i=0;i<4;i++){store(0xfe00+4*i,36+24*i);store(0xfe02+4*i,1);store(0xfe03+4*i,cgb?i:0);}
 if(cgb){
  store(0xff4f,1);emit(0x21,0,0x98,0x01,0,4);label('attrs');emit(0xaf,0x22,0x0b,0x78,0xb1);jump(0xc2,'attrs');store(0xff4f,0);
  store(0xff68,0x80);for(const v of [0xff,0x7f,0,0,0x1f,0,0,0x7c])store(0xff69,v);
  store(0xff6a,0x80);for(const color of [0x001f,0x03e0,0x7c00,0x03ff])for(const v of [0xff,0x7f,0,0,0,0,color&255,color>>8])store(0xff6b,v);
  store(0xff70,2);store(0xd0f0,0x99); // physical bank 2 must not change discovery
 }
 store(0xff47,0xe4);store(0xff48,0xe4);
 // Pulse channel: replay output must never be emitted, even though APU state is simulated.
 for(const [a,v]of [[0xff26,0x80],[0xff24,0x77],[0xff25,0x11],[0xff11,0x80],[0xff12,0xf0],[0xff13,0x80],[0xff14,0x87]])store(a,v);
 store(0xff40,0x93);
 label('frame');emit(0xf0,0x44,0xfe,144);jump(0xc2,'frame');
 for(let i=0;i<4;i++){
  emit(0xfa,0x10+i,0xc4,0xe6,1);jump(0xca,'left'+i);emit(0x21,i,0xc0,0x34);
  label('left'+i);emit(0xfa,0x10+i,0xc4,0xe6,2);jump(0xca,'action'+i);emit(0x21,i,0xc0,0x35);
  label('action'+i);emit(0xfa,0x10+i,0xc4,0xe6,16);jump(0xca,'draw'+i);emit(0x21,8,0xc0,0x34);
  label('draw'+i);emit(0xfa,i,0xc0,0xea,1+i*4,0xfe);
 }
 emit(0x21,4,0xc0,0x34); // world tick, independent of view
 emit(0xfa,3,0xc4,0xfe,0xff);jump(0xc2,'player');emit(0xaf);
 label('player');emit(0x4f,0x87,0x81,0xe0,0x43); // fixed camera = slot × 3; distinct even when actors coincide
 label('end');emit(0xf0,0x44,0xfe,144);jump(0xca,'end');jump(0xc3,'frame');
 for(const [at,n]of fixups){const value=labels.get(n);rom[at]=value&255;rom[at+1]=value>>8;}
 rom.set([0,0xc3,0x50,1],0x100);
 rom.set([0xce,0xed,0x66,0x66,0xcc,0x0d,0,0x0b,3,0x73,0,0x83,0,0x0c,0,0x0d,0,8,0x11,0x1f,0x88,0x89,0,0x0e,0xdc,0xcc,0x6e,0xe6,0xdd,0xdd,0xd9,0x99,0xbb,0xbb,0x67,0x63,0x6e,0x0e,0xec,0xcc,0xdd,0xdc,0x99,0x9f,0xbb,0xb9,0x33,0x3e],0x104);
 // Include 32 KiB cartridge RAM: the performance gate must not use a smaller
 // RAM-free snapshot than the external M1 fixture. The bundle zeroes it at boot.
 rom[0x147]=0x1b;rom[0x149]=3;
 return fixHeader(rom,cgb?'gbc':'gb','MP BUNDLE');
}
